/**
 * @name Potential attribute injection
 * @description Using getattr/hasattr with potentially untrusted attribute names
 * @kind path-problem
 * @problem.severity warning
 * @id py/attribute-injection
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module AttributeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["getattr", "hasattr", "setattr", "delattr"]).getACall() and
      sink = call.getArg(1) // The attribute name argument
    )
  }
}

module AttributeInjectionFlow = TaintTracking::Global<AttributeInjectionConfig>;
import AttributeInjectionFlow::PathGraph

from AttributeInjectionFlow::PathNode source, AttributeInjectionFlow::PathNode sink
where AttributeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially unsafe attribute access with user-controlled name from $@.", source, "parameter"
